      '.aml-dogh{text-align:left;width:91.666667%;margin:0 auto 4px;border:1px solid #E5E5E7;border-radius:8px;',
      'padding:10px 12px;background:#FFF;font-family:"Noto Sans",Lato,sans-serif;box-sizing:border-box;}',
      '.aml-dogh:after{content:"";display:block;clear:both;}',
      '.aml-dogh__q{font-size:12px;line-height:1.4;color:#424752;margin:0;}',
      // 11px / #505662 — matches the "Education*" label on the page
      '.aml-dogh__more{display:inline-block;margin-top:2px;font-size:11px;font-weight:600;',
      'color:#505662;cursor:pointer;text-decoration:underline;user-select:none;}',
      '.aml-dogh__more:hover{color:#252931;}',
      '.aml-dogh__list{max-height:0;overflow:hidden;transition:max-height .28s ease;',
      'margin:0;padding:0;list-style:none;}',
      '.aml-dogh.is-open .aml-dogh__list{max-height:260px;}',
      '.aml-dogh__list li{position:relative;padding-left:16px;margin-top:5px;font-size:12px;',
      'line-height:1.4;color:#505662;}',
      '.aml-dogh__list li:first-child{margin-top:6px;}',
      '.aml-dogh__list li:before{content:"";position:absolute;left:4px;top:7px;width:5px;height:5px;',
      'border-radius:50%;background:#97144D;}',
      // Yes/No toggle — mirrors the gender/education pill styling.
      // Floated (not flex) so the question text wraps around it instead of being
      // squeezed into a narrow column on mobile.
      // margin-bottom is deliberately 2px: the float must clear before the third
      // text line, otherwise the question wraps to an orphan word.
      '.aml-dogh__toggle{float:right;display:flex;margin:0 0 2px 10px;border:1px solid #CBCCD0;',
      'border-radius:8px;overflow:hidden;background:#FFF;}',
      '.aml-dogh__opt{appearance:none;-webkit-appearance:none;border:0;background:#FFF;',
      'min-width:40px;padding:6px 8px;font-family:inherit;font-size:12px;font-weight:600;',
      'color:#505662;cursor:pointer;line-height:1.2;}',
      '.aml-dogh__opt+.aml-dogh__opt{border-left:1px solid #CBCCD0;}',
      '.aml-dogh__opt[aria-pressed="true"]{background:#EAF4FD;color:#252931;',
      'box-shadow:inset 0 0 0 1px #4A90D9;}',
      // the modal is pinned to height:28rem by the site CSS, which pushes the
      // "Select Plans" CTA into an inner scroll area once the DOGH block is added.
      // Let the white panel grow to fit its content instead (max-height:90% still caps it).
      '.nri-education-popup .modal .modal-content.aml-dogh-modal{height:auto!important;max-height:90%!important;}'
